def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    last_me, last_opp = history[-1]
    if last_opp == 'C':
        return 'C'
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_d += 1
        else:
            break
    if consec_d >= 3:
        if rng.random() < 0.1:
            return 'C'
        return 'D'
    if consec_d == 2:
        if rng.random() < 0.2:
            return 'C'
        return 'D'
    return 'D'
